var QUESTOES_ENCONTROSCONSONANTAIS = [{"id":6,"enunciado":"Todas as palavras a seguir aparecem no texto. A que apresenta um encontro consonantal é","opcoes":["alunos.","área.","cada.","pessoas.","travestidas."],"correta":4,"explicacao":"Gabarito: <strong>travestidas.</strong>.","banca":"Fundação CETREDE","ano":2025,"temas_relacionados":["encontrosConsonantais"]},{"id":7,"enunciado":"Nas palavras PRECONCEITO, SAÚDE e MINHA são identificados, respectivamente.","opcoes":["Dígrafo, encontro consonantal, ditongo.","Ditongo, encontro consonantal, dígrafo.","Dígrafo, hiato, encontro consonantal.","Encontro consonantal, dígrafo, hiato.","Encontro consonantal, hiato, dígrafo."],"correta":4,"explicacao":"Gabarito: <strong>Encontro consonantal, hiato, dígrafo.</strong>.","banca":"Ápice Consultoria","ano":2025,"temas_relacionados":["encontrosConsonantais","hiatos","digrafos"]},{"id":18,"enunciado":"Sobre a palavra \"demográfica\", analise as assertivas: I. Apresenta um hiato. II. É composta por cinco sílabas. III. Contém um encontro consonantal. Está correto o que se afirma em:","opcoes":["I, apenas.","I e II, apenas.","II e III, apenas.","I, II e III."],"correta":2,"explicacao":"Gabarito: <strong>II e III, apenas.</strong>.","banca":"Instituto Fênix","ano":2024,"temas_relacionados":["encontrosConsonantais","hiatos","silabas"]},{"id":23,"enunciado":"Nas palavras TUNGSTÊNICO, ABSORTO, QUENTE, GUARDIÃO e EXCEPCIONAL, temos:","opcoes":["Dois encontros consonantais, dois dígrafos, um dígrafo e um encontro consonantal.","Dois encontros consonantais, um dígrafo, um encontro vocálico, um dígrafo e um encontro consonantal.","Dois encontros consonantais, um dígrafo, um encontro vocálico e dois encontros consonantais.","Dois encontros consonantais, um encontro vocálico, dois dígrafos e um encontro consonantal.","Dois encontros consonantais, três encontros vocálicos, um encontro consonantal."],"correta":1,"explicacao":"Gabarito: <strong>Dois encontros consonantais, um dígrafo, um encontro vocálico, um dígrafo e um encontro consonantal.</strong>.","banca":"LJ Assessoria e Planejamento Administrativo Limita","ano":2024,"temas_relacionados":["encontrosConsonantais","digrafos","ditongos","hiatos","tritongos"]},{"id":49,"enunciado":"“A iniciativa promove a colaboração e o intercâmbio entre as instituições, estudantes e acadêmicos por meio de programas de pesquisa.” Assinale a alternativa CORRETA.","opcoes":["Em “iniciativa”, ocorre um hiato.","Em “colaboração”, ocorre um dífono nasal.","Em “meio”, ocorre um tritongo.","Em “programas”, ocorre apenas um encontro consonantal.","Em “pesquisa”, ocorre um ditongo."],"correta":0,"explicacao":"Gabarito: <strong>Em “iniciativa”, ocorre um hiato.</strong>.","banca":"EDUCA","ano":2025,"temas_relacionados":["encontrosConsonantais","hiatos"]},{"id":71,"enunciado":"Em relação à fonética e fonologia das palavras, analise os itens abaixo: I. Em “desigual”, ocorre um tritongo. II. Em “preconceituosa”, ocorrem dois ditongos decrescentes. III. Em “discriminação”, ocorre um encontro consonantal disjunto. IV. Em “preconceito”, ocorre um encontro consonantal puro e um hiato. V. Em “estereótipos”, ocorre um encontro consonantal disjunto e um hiato. Assinale a alternativa correta sobre os encontros vocálicos e encontros consonantais citados acima.","opcoes":["Somente os itens I e V estão corretos.","Somente os itens II e IV estão corretos.","Somente os itens II, III e IV estão corretos.","Somente os itens I, III e V estão corretos."],"correta":3,"explicacao":"Gabarito: <strong>Somente os itens I, III e V estão corretos.</strong>.","banca":"Instituto Darwin","ano":2024,"temas_relacionados":["encontrosConsonantais","ditongos","tritongos","hiatos"]},{"id":75,"enunciado":"Na palavra \"democracia\", há a ocorrência de:","opcoes":["Encontro consonantal e hiato.","Encontro consonantal e ditongo.","Dígrafo e hiato.","Dígrafo e ditongo."],"correta":0,"explicacao":"Gabarito: <strong>Encontro consonantal e hiato.</strong>.","banca":"DAE de Bauru - SP","ano":2024,"temas_relacionados":["encontrosConsonantais","hiatos"]},{"id":90,"enunciado":"Na palavra OPINIÃO, há:","opcoes":["um tritongo","um hiato e um dígrafo","um hiato e um ditongo","um encontro consonantal e um hiato","um encontro consonantal e um dígrafo"],"correta":2,"explicacao":"Gabarito: <strong>um hiato e um ditongo</strong>.","banca":"SELECON","ano":2024,"temas_relacionados":["encontrosConsonantais","ditongos","hiatos"]},{"id":105,"enunciado":"A fonética é o estudo dos sons da fala e trata dos fonemas, da pronúncia correta das palavras, da exata acentuação tônica e da configuração gráfica ou a escrita correta das palavras, denominada ortografia. Considere esse conceito e leia a tirinha. Imagem associada para resolução da questão Disponível em: <https://www.nsctotal.com.br/noticias/confira-a-tira-do-armandinho-desta-terca-feira-4>. Avalie o que se informa acerca das palavras que compõem o texto da tirinha. I – A palavra “extintas” deve ser acentuada, pois se trata de uma paroxítona terminada em “s”. II – A expressão “preguiças-gigantes” foi grafada com hífen porque corresponde a um adjetivo composto. III – O último quadrinho da tira traz alguns vocábulos formados por ditongo, dígrafo e encontro consonantal. Está correto apenas o que se afirma em","opcoes":["II.","III.","I e II.","I e III. Resposta correta"],"correta":3,"explicacao":"Gabarito: <strong>I e III. Resposta correta</strong>.","banca":"FCM","ano":2022,"temas_relacionados":["encontrosConsonantais","ditongos","digrafos","paroxitonas","fonemas","ortografia","hifen"]},{"id":121,"enunciado":"Em se tratando do Texto 1, os grupos de letras encontrados nas palavras “lavoura”, “repentista” e “pressas” são, respectivamente, chamados de","opcoes":["ditongo e encontros consonantais inseparáveis.","ditongos e encontros consonantais inseparáveis e separáveis.","ditongo, dígrafo, encontros consonantais separáveis, encontro consonantal inseparável e dígrafos.","encontros vocálicos e dígrafos."],"correta":2,"explicacao":"Gabarito: <strong>ditongo, dígrafo, encontros consonantais separáveis, encontro consonantal inseparável e dígrafos.</strong>.","banca":"Instituto Access","ano":2024,"temas_relacionados":["encontrosConsonantais","ditongos","digrafos"]},{"id":123,"enunciado":"Analise foneticamente a palavra “desconhecidos”. Ela apresenta:","opcoes":["Apenas dígrafo.","Apenas encontro consonantal.","Dígrafo e ditongo aberto.","Dígrafo e encontro consonantal.","Nem dígrafo, nem encontro consonantal."],"correta":3,"explicacao":"Gabarito: <strong>Dígrafo e encontro consonantal.</strong>.","banca":"FUNDATEC","ano":2024,"temas_relacionados":["encontrosConsonantais","digrafos"]},{"id":138,"enunciado":"A relação do motorista de aplicativo com a plataforma é um vínculo de emprego? Ou ele é um trabalhador independente que contrata a tecnologia dessas empresas? Assinale a opção que contenha encontro consonantal e vocálico, simultaneamente, em pelo menos um dos vocábulos.","opcoes":["aplicativo - plataforma","um - que","de - ou","tecnologia - dessas","motorista - trabalhador"],"correta":3,"explicacao":"Gabarito: <strong>tecnologia - dessas</strong>.","banca":"AMAUC","ano":2024,"temas_relacionados":["encontrosConsonantais"]},{"id":167,"enunciado":"Analise a separação silábica, a classificação tônica e os encontros vocálicos e consonantais e assinale a alternativa em que ocorre falha:","opcoes":["pe-tró-leo / paroxítona / encontro consonantal(tr) / ditongo(eo).","res-pec-ti-va-men-te / paroxitona / encontro consonantal (ct) / dígrafo (men).","cor-ro-bo-ran-do / paroxítona / encontro consonantal(rr) / digrafo(an).","So-vi-é-ti-ca / proparoxitona / hiato(i-é)."],"correta":2,"explicacao":"Gabarito: <strong>cor-ro-bo-ran-do / paroxítona / encontro consonantal(rr) / digrafo(an).</strong>.","banca":"Fundação CETAP","ano":2021,"temas_relacionados":["encontrosConsonantais","digrafos","silabas","paroxitonas"]},{"id":169,"enunciado":"Qual das seguintes palavras apresenta encontro vocálico e encontro consonantal?","opcoes":["Próximo.","Cuidado.","Brasileiros.","Tarefas.","Movimento."],"correta":2,"explicacao":"Gabarito: <strong>Brasileiros.</strong>.","banca":"FUNDATEC","ano":2024,"temas_relacionados":["encontrosConsonantais","ditongos","hiatos","tritongos"]},{"id":174,"enunciado":"'O planeta Terra talvez continuasse fazendo parte da Via Láctea'. É CORRETO afirmar que o vocábulo:","opcoes":["'Láctea' apresenta um encontro consonantal e dois vocálicos.","'planeta' possui um encontro vocálico e um consonantal.","'continuasse' possui um encontro consonantal, um vocálico e um dígrafo.","'terra' consiste de um encontro consonantal e um dígrafo."],"correta":2,"explicacao":"Gabarito: <strong>'continuasse' possui um encontro consonantal, um vocálico e um dígrafo.</strong>.","banca":"AMEOSC","ano":2022,"temas_relacionados":["encontrosConsonantais","digrafos"]},{"id":177,"enunciado":"A palavra que contém um encontro consonantal é:","opcoes":["Legado.","Piloto.","Velório.","Coração.","Esporte."],"correta":4,"explicacao":"Gabarito: <strong>Esporte.</strong>.","banca":"FUNDATEC","ano":2024,"temas_relacionados":["encontrosConsonantais"]},{"id":181,"enunciado":"Considerando os processos fonológicos e de formação de palavras da Língua Portuguesa, analise as assertivas a seguir: I.    As palavras “amanhecido” e “expatriado” são formadas por derivação parassintética. II.   A palavra “companhia” contém um encontro consonantal e um dígrafo. III. “Padaria” é uma palavra que contém um ditongo aberto. Quais estão corretas?","opcoes":["Apenas I.","Apenas II.","Apenas I e III.","Apenas II e III.","I, II e III."],"correta":0,"explicacao":"Gabarito: <strong>Apenas I.</strong>.","banca":"FUNDATEC","ano":2024,"temas_relacionados":["encontrosConsonantais","ditongos","digrafos"]},{"id":184,"enunciado":"Na palavra “programação”, os elementos sublinhados constituem um exemplo de:","opcoes":["Dígrafo.","Encontro consonantal perfeito.","Encontro consonantal imperfeito.","Ditongo."],"correta":1,"explicacao":"Gabarito: <strong>Encontro consonantal perfeito.</strong>.","banca":"Instituto Fênix","ano":2023,"temas_relacionados":["encontrosConsonantais"]},{"id":195,"enunciado":"São palavras da narrativa acima que apresentam, ambas, tanto encontro vocálico quanto encontro consonantal:","opcoes":["Confiança – Estacionamento.","Granada – Com.","Rompante – Puxou.","Jogou – Fogo.","Extintor – Nervosa."],"correta":0,"explicacao":"Gabarito: <strong>Confiança – Estacionamento.</strong>.","banca":"ADVISE","ano":2022,"temas_relacionados":["encontrosConsonantais","ditongos","hiatos","tritongos"]},{"id":198,"enunciado":"O vocábulo ‘distraído’ , presente no texto II, apresenta, na sequência:","opcoes":["um dígrafo e um encontro consonantal.","um dífono e um ditongo.","um encontro consonantal e um hiato.","um hiato e um ditongo."],"correta":2,"explicacao":"Gabarito: <strong>um encontro consonantal e um hiato.</strong>.","banca":"Aroeira","ano":2023,"temas_relacionados":["encontrosConsonantais","hiatos"]},{"id":199,"enunciado":"A combinação das letras no vocábulo ‘oxigênio’ apresenta.","opcoes":["um encontro consonantal.","um dígrafo.","um hiato.","um dífono."],"correta":3,"explicacao":"Gabarito: <strong>um dífono.</strong>.","banca":"Aroeira","ano":2023,"temas_relacionados":["encontrosConsonantais"]},{"id":202,"enunciado":"Outra razão bastante frequente para o abandono dos medicamentos são os efeitos indesejados sobre o corpo. Em relação a questões ortográficas, é correto afirmar que, no vocábulo:","opcoes":["'bastante', há um encontro vocálico e dois encontros consonantais.","'outra', há encontro vocálico seguido de encontro consonantal.","'medicamentos', tem-se dois encontros consonantais.","'indesejados', não há encontro vocálico nem encontro consonantal.","'frequente', percebe-se a presença de dígrafo."],"correta":1,"explicacao":"Gabarito: <strong>'outra', há encontro vocálico seguido de encontro consonantal.</strong>.","banca":"Unesc","ano":2023,"temas_relacionados":["encontrosConsonantais","ditongos","hiatos","tritongos"]},{"id":203,"enunciado":"Leia o texto a seguir, início do capítulo “O Homem Sábio”, constante do livro 1822, de Laurentino Gomes (São Paulo: Globo, 2015 p. 143, adaptado): Dois anos depois da Independência do Brasil, José Bonifácio de Andrada e Silva pediu autorização ao rei dom João VI para voltar a Santos, cidade em que nascera, no litoral paulista. Depois de viver muitos anos na Europa, sentia-se velho e cansado. De acordo com sua psicologia, queria morrer em paz ao lado dos familiares. Como era funcionário graduado da coroa portuguesa, dependia de aprovação para continuar a receber seus vencimentos no Brasil. Os pedidos, insistentes, se repetiam havia uma década, contudo eram sempre negados. “Estou doente, aflito e cansado”, queixava-se a dom Rodrigo de Sousa Coutinho, futuro conde de Linhares, já em 26 de maio de 1806. “Logo que acabe meu tempo em Coimbra, vou deitar-me sem mágoa aos pés de Sua Alteza Real (o príncipe regente dom João) para que me deixe ir acabar o resto dos meus cansados dias nos vácuos dos sertões do Brasil a cultivar o que é meu”. Assinale a alternativa INCORRETA a respeito de encontros vocálicos e consonantais do texto:","opcoes":["Apresentam ditongos nasais as seguintes palavras: “repetiam”, “autorização”, “muitos”.","Apresentam ditongos decrescentes as seguintes palavras: “depois”, “Sousa”, “deixe”.","Apresentam encontros consonantais perfeitos as seguintes palavras: “psicologia”, “Rodrigo”, “Brasil”.","Apresentam encontros consonantais imperfeitos as seguintes palavras: “voltar”, “cansados”, “Alteza”.","Apresentam ditongos crescentes as seguintes palavras: “Bonifácio”, “vácuos”, “mágoa”."],"correta":3,"explicacao":"Gabarito: <strong>Apresentam encontros consonantais imperfeitos as seguintes palavras: “voltar”, “cansados”, “Alteza”.</strong>.","banca":"COMVEST UFAM","ano":2023,"temas_relacionados":["encontrosConsonantais","ditongos"]},{"id":205,"enunciado":"No vocábulo desprezar, encontramos","opcoes":["um dígrafo vocálico.","um dígrafo consonantal.","um encontro vocálico.","um encontro consonantal.","um ditongo vocálico."],"correta":3,"explicacao":"Gabarito: <strong>um encontro consonantal.</strong>.","banca":"IDIB","ano":2023,"temas_relacionados":["encontrosConsonantais"]},{"id":206,"enunciado":"Julgue os itens a seguir: 01 – Em “clara” e “livro” temos exemplos de encontro consonantal perfeito. 02 – Nas palavras “piada” e “ciúme” temos exemplos de hiato. 04 – Em “guerra”, “ninho” e “carro”, temos um total de quatro dígrafos. 08 – Em “tranquilo” e “quase”, temo um total de zero dígrafos. O somatório das alternativas corretas é:","opcoes":["14","10","07","15","11"],"correta":2,"explicacao":"Gabarito: <strong>07</strong>.","banca":"LJ Assessoria e Planejamento Administrativo Limita","ano":2023,"temas_relacionados":["encontrosConsonantais","hiatos","digrafos"]},{"id":209,"enunciado":"Marque o que não se comprova no segmento transcrito a seguir: “Por obrigação profissional e por obsessão nas horas vagas, costumo conversar muito sobre livros”.","opcoes":["A frase está estruturada com hipérbato ou inversão.","A palavra: “obrigação” está escrita com encontro consonantal e ditongo nasal.","A expressão “nas horas vagas” tem sentido adverbial de tempo, formado de contração prepositiva, substantivo e adjetivo no feminino plural.","A única oração do segmento está escrita com sujeito elíptico; verbos de primeira conjugação formando locução verbal; antítese de pouco; preposição essencial dissílaba paroxítona com encontro consonantal, e um dissílabo paroxítono que tem “biblioteca” como seu coletivo.","A frase está escrita com exemplo de gradação e pleonasmo vicioso."],"correta":4,"explicacao":"Gabarito: <strong>A frase está escrita com exemplo de gradação e pleonasmo vicioso.</strong>.","banca":"MS Concursos e Consultoria","ano":2023,"temas_relacionados":["encontrosConsonantais"]},{"id":225,"enunciado":"A palavra “pai” apresenta qual encontro vocálico?","opcoes":["Hiato.","Ditongo.","Um encontro consonantal falso.","Tritongo.","Dois hiatos."],"correta":1,"explicacao":"Gabarito: <strong>Ditongo.</strong>.","banca":"Instituto IACP","ano":2026,"temas_relacionados":["encontrosConsonantais","ditongos","hiatos","tritongos"]},{"id":227,"enunciado":"Considerando os processos fonológicos, analisar os itens. I. Em “enxáguem”, temos um tritongo nasal. II. Em “papagaio” e “meio”, temos exemplo de tritongo. III. Em “Piauí”, temos dois hiatos e um ditongo. IV. Em “samba” e “antigo”, temos encontro consonantal. Está CORRETO o que se afirma:","opcoes":["Apenas nos itens I e II.","Apenas nos itens I e III.","Apenas nos itens I, III e IV.","Apenas nos itens II, III e IV."],"correta":1,"explicacao":"Gabarito: <strong>Apenas nos itens I e III.</strong>.","banca":"Objetiva Concursos","ano":2025,"temas_relacionados":["encontrosConsonantais","ditongos","tritongos","hiatos"]},{"id":237,"enunciado":"A palavra “preenchidos” é formada por:","opcoes":["Dois encontros consonantais e dois dígrafos.","Um encontro consonantal e um dígrafo.","Dois dígrafos e um encontro vocálico.","Dois encontros consonantais e um encontro vocálico.","Um encontro consonantal, um encontro vocálico e um dígrafo."],"correta":4,"explicacao":"Gabarito: <strong>Um encontro consonantal, um encontro vocálico e um dígrafo.</strong>.","banca":"FUNDATEC","ano":2023,"temas_relacionados":["encontrosConsonantais","digrafos","ditongos","hiatos","tritongos"]},{"id":251,"enunciado":"Analise as frases seguintes com as informamos seguidas a elas. I – Não se tem uma explicação sobre isto. – Sublinhamos um substantivo com encontro consonantal e ditongo nasal decrescente; e uma preposição com encontro consonantal.  II – Busque a Felicidade! - Sublinhamos um verbo com dígrafo. III – Por medo de chorar, deixamos de sorrir. - Sublinhamos verbos na forma nominal do infinitivo que são antônimos, estando cada um está escrito com dígrafo. IV - E perder sua própria identidade. – Sublinhamos um pronome escrito com hiato e um adjetivo biforme escrito com idênticos encontros consonantais. Marque a alternativa cujas frases estão com análise correta.","opcoes":["I; II; III e IV.","Apenas I e II.","Apenas II e IV.","Apenas I; II e IV.","Apenas I e III."],"correta":0,"explicacao":"Gabarito: <strong>I; II; III e IV.</strong>.","banca":"MS Consultoria","ano":2023,"temas_relacionados":["encontrosConsonantais","ditongos","hiatos","digrafos"]},{"id":252,"enunciado":"Marque a alternativa que apresenta um substantivo abstrato escrito com encontro consonantal e hiato; e um pronome escrito com hiato.","opcoes":["Alegria; sua.","Indignos; melhor.","Crescer; sorrir.","Sempre; conflitos.","Hábitos; felicidade."],"correta":0,"explicacao":"Gabarito: <strong>Alegria; sua.</strong>.","banca":"MS Consultoria","ano":2023,"temas_relacionados":["encontrosConsonantais","hiatos"]},{"id":260,"enunciado":"O tema será melhor afinado se ficarmos entre 16 e 25 anos. Assinale a alternativa CORRETA.","opcoes":["O vocábulo 'ficarmos' possui dois encontros consonantais.","No vocábulo 'afinado', encontra-se um encontro consonantal.","O vocábulo 'entre' possui um encontro consonantal e um dígrafo.","No vocábulo 'melhor', tem-se um dígrafo, expresso pelo 'lh'."],"correta":3,"explicacao":"Gabarito: <strong>No vocábulo 'melhor', tem-se um dígrafo, expresso pelo 'lh'.</strong>.","banca":"IDCAP","ano":2022,"temas_relacionados":["encontrosConsonantais","digrafos"]},{"id":261,"enunciado":"A palavra “atualmente” tem:","opcoes":["Dois encontros consonantais e nenhum dígrafo.","Nenhum encontro consonantal e dois dígrafos.","Um encontro consonantal e um dígrafo.","Um encontro consonantal e nenhum dígrafo.","Nenhum encontro consonantal e um dígrafo."],"correta":2,"explicacao":"Gabarito: <strong>Um encontro consonantal e um dígrafo.</strong>.","banca":"FUNDATEC","ano":2023,"temas_relacionados":["encontrosConsonantais","digrafos"]},{"id":265,"enunciado":"Assinale a alternativa que apresenta uma palavra com encontro consonantal localizado na mesma sílaba.","opcoes":["Parte.","Jornal.","Brasil.","Louros.","Jornalística."],"correta":2,"explicacao":"Gabarito: <strong>Brasil.</strong>.","banca":"FUNDATEC","ano":2023,"temas_relacionados":["encontrosConsonantais","silabas"]},{"id":267,"enunciado":"Observe o seguinte texto: “... acha uma lindeza os barcos veleiros coloridos ...” Considere as palavras ‘acha’ – ‘veleiros’ – ‘pretendentes’ e analise as afirmativas: I. Identifica-se a ocorrência de dígrafo em ‘acha’. II. Em ‘veleiros’ apresenta-se ditongo crescente. III. Tem-se um encontro consonantal em ‘barcos’. É correto o que se afirma:","opcoes":["Apenas em I.","Apenas em II.","Apenas em I e II.","Apenas em I e III.","Apenas em II e III."],"correta":3,"explicacao":"Gabarito: <strong>Apenas em I e III.</strong>.","banca":"IDECAN","ano":2023,"temas_relacionados":["encontrosConsonantais","ditongos","digrafos"]},{"id":295,"enunciado":"A respeito das palavras retiradas do texto “Plantas tóxicas: lindas e perigosas”, é correto afirmar que há","opcoes":["dígrafo em “pesquisa”, hiato em “alergia”, encontro consonantal em “pessoa” e ditongo em “coceira”.","encontro consonantal em “planta”, ditongo em “náusea”, dígrafo em “espirradeira” e tritongo em “diarreia”.","dígrafo em “quadro” e em “tinhorão”, encontro consonantal em “flor” e ditongo em “pandemia”.","encontro consonantal e dígrafo em “quadro” e em “exemplo” e encontro consonantal e hiato em “primeiro”.","encontro consonantal e hiato em “agropecuária”, dígrafo em “atendimento” e ditongo em “grau”."],"correta":4,"explicacao":"Gabarito: <strong>encontro consonantal e hiato em “agropecuária”, dígrafo em “atendimento” e ditongo em “grau”.</strong>.","banca":"INSTITUTO AOCP","ano":2021,"temas_relacionados":["encontrosConsonantais","ditongos","hiatos","digrafos"]},{"id":299,"enunciado":"Assinale a alternativa correta.","opcoes":["No vocábulo “grande” há somente um grupo consonantal.","No vocábulo “filha” há um dígrafo.","Em “ruim” há hiato.","Todas as alternativas são corretas."],"correta":3,"explicacao":"Gabarito: <strong>Todas as alternativas são corretas.</strong>.","banca":"CONSESP","ano":2018,"temas_relacionados":["encontrosConsonantais"]},{"id":308,"enunciado":"Considerando a palavra “contraídas”, analise as assertivas a seguir: I. Pode-se identificar a presença de um ditongo na palavra. II. A palavra apresenta 10 letras e 9 fonemas. III. Tem-se nela um encontro consonantal. Quais estão corretas?","opcoes":["Apenas I.","Apenas II.","Apenas I e II.","Apenas I e III.","Apenas II e III."],"correta":4,"explicacao":"Gabarito: <strong>Apenas II e III.</strong>.","banca":"FUNDATEC","ano":2022,"temas_relacionados":["encontrosConsonantais","ditongos","fonemas"]},{"id":313,"enunciado":"'A Grande Barreira de Corais da Austrália está sofrendo um branqueamento massivo, devido às altas temperaturas do mar'. Assinale a opção CORRETA.","opcoes":["Na expressão 'altas temperaturas do mar', as palavras 'altas' e 'mar' constituem exemplos de encontros consonantais.","A palavra 'Corais' apresenta um hiato como encontro vocálico.","Na expressão 'Grande Barreira', temos, pelo menos, um encontro consonantal, um dígrafo e um ditongo.","A expressão 'branqueamento massivo' nos apresenta dois encontros consonantais, um ditongo e dois dígrafos."],"correta":2,"explicacao":"Gabarito: <strong>Na expressão 'Grande Barreira', temos, pelo menos, um encontro consonantal, um dígrafo e um ditongo.</strong>.","banca":"AMEOSC","ano":2022,"temas_relacionados":["encontrosConsonantais","ditongos","digrafos"]},{"id":323,"enunciado":"Sobre o vocábulo ‘Provavelmente’ (l. 04), é correto afirmar que:","opcoes":["Tem tantas letras quanto fonemas.","Possui um dígrafo vocálico e dois encontros consonantal.","Tem um encontro vocálico.","É formado por derivação sufixal e prefixal.","Possui desinência adverbial."],"correta":1,"explicacao":"Gabarito: <strong>Possui um dígrafo vocálico e dois encontros consonantal.</strong>.","banca":"FUNDATEC","ano":2022,"temas_relacionados":["encontrosConsonantais","digrafos"]},{"id":326,"enunciado":"Analise, foneticamente, a palavra “Pesquisadores”. Ela apresenta:","opcoes":["Apenas dígrafo.","Apenas encontro consonantal.","Dígrafo e ditongo aberto.","Dígrafo e encontro consonantal.","Nem dígrafo, nem encontro consonantal."],"correta":3,"explicacao":"Gabarito: <strong>Dígrafo e encontro consonantal.</strong>.","banca":"FUNDATEC","ano":2021,"temas_relacionados":["encontrosConsonantais","digrafos"]},{"id":332,"enunciado":"As palavras “Quero”, “Lua” e “estrelas” são formadas, respectivamente, por","opcoes":["encontro consonantal / hiato / dígrafo.","dígrafo / hiato / encontro consonantal.","encontro vocálico / encontro vocálico / dígrafo.","encontro consonantal / ditongo / encontro vocálico.","encontro consonantal / encontro vocálico / encontro consonantal."],"correta":1,"explicacao":"Gabarito: <strong>dígrafo / hiato / encontro consonantal.</strong>.","banca":"FCM","ano":2021,"temas_relacionados":["encontrosConsonantais","hiatos","digrafos"]},{"id":334,"enunciado":"Nos vocábulos arquiteta e comissões aparecem os seguintes fenômenos fonéticos, respectivamente:","opcoes":["Ditongo oral – Dígrafo.","Dígrafo – Dígrafo e ditongo nasal.","Encontro consonantal – Dígrafo vocálico.","Ditongo oral – Ditongo nasal.","Encontro consonantal e dígrafo – Encontro consonantal."],"correta":1,"explicacao":"Gabarito: <strong>Dígrafo – Dígrafo e ditongo nasal.</strong>.","banca":"FUNDATEC","ano":2021,"temas_relacionados":["encontrosConsonantais","ditongos","digrafos"]},{"id":355,"enunciado":"Examine o enunciado presente no texto I: “19 milhões passam fome no Brasil” Considerando os aspectos fonéticos e fonológicos de tal enunciado, informe se é verdadeiro (V) ou falso (F) o que se afirma a seguir e assinale a alternativa com a sequência correta. ( ) Em “milhões”, há o uso de “lh” em uma mesma sílaba – um caso de encontro consonantal. ( ) Há, no termo “milhões”, um ditongo decrescente em “ões”. ( ) Em “passam”, há seis letras e respectivos seis fonemas. ( ) O uso de “ss”, no vocábulo “passam”, corresponde a um dígrafo. ( ) No substantivo “Brasil”, o encontro das consoantes “b” e “r” configura um encontro consonantal.","opcoes":["F – F – F – V – V.","F – V – V – V – F.","F – V – F – V – V.","V – V – F – F – V.","V - F – V – F – V."],"correta":2,"explicacao":"Gabarito: <strong>F – V – F – V – V.</strong>.","banca":"AOCP","ano":2021,"temas_relacionados":["encontrosConsonantais","ditongos","digrafos","silabas","fonemas"]},{"id":367,"enunciado":"Sobre o período: \"O falar é a prata das emoções, enquanto o calar representa o ouro no peso do seu quilate, logo, tem maior valor\", marque a alternativa INCORRETA.","opcoes":["A primeira oração está escrita com metáfora.","O núcleo do sujeito de cada uma das orações: \"O falar é a prata das emoções\" e \"O calar representa o ouro\" está representado por substantivo formado por derivação imprópria.","Dentre os termos que compõem o período, temos exemplos de: encontros consonantais, encontros vocálicos e dígrafo.","No trecho: \"o ouro no peso do seu quilate\", temos contrações prepositivas impostas pela regência verbal."],"correta":3,"explicacao":"Gabarito: <strong>No trecho: \"o ouro no peso do seu quilate\", temos contrações prepositivas impostas pela regência verbal.</strong>.","banca":"IDCAP","ano":2021,"temas_relacionados":["encontrosConsonantais","digrafos","ditongos","hiatos","tritongos"]},{"id":369,"enunciado":"Sobre o período: \"O falar é a prata das emoções, enquanto o calar representa o ouro no peso do seu quilate, logo, tem maior valor\", marque a alternativa INCORRETA.","opcoes":["A primeira oração está escrita com metáfora.","O núcleo do sujeito de cada uma das orações: \"O falar é a prata das emoções\" e \"O calar representa o ouro\" está representado por substantivo formado por derivação imprópria.","No trecho: \"o ouro no peso do seu quilate\", temos contrações prepositivas impostas pela regência verbal.","Dentre os termos que compõem o período, temos exemplos de: encontros consonantais, encontros vocálicos e dígrafo."],"correta":2,"explicacao":"Gabarito: <strong>No trecho: \"o ouro no peso do seu quilate\", temos contrações prepositivas impostas pela regência verbal.</strong>.","banca":"IDCAP","ano":2021,"temas_relacionados":["encontrosConsonantais"]},{"id":372,"enunciado":"Acerca dos encontros vocálicos e consonantais, analise: I - Dá-se o nome de encontro consonantal à sequência de consoantes num vocábulo, ou seja, a contiguidade de duas ou três consoantes efetivamente pronunciadas; II - Quando as duas consoantes se encontram em uma mesma sílaba, diz-se que o encontro consonantal é próprio ou perfeito. Quando as consoantes ficam em sílabas diferentes, diz-se que o é um encontro consonantal impróprio ou imperfeito; III - Encontro vocálico é a sucessão de vogais em um vocábulo – gaiola, Bahia, caule, Uruguai, averiguei. Classificam-se em: ditongo, hiato e tritongo. Dos itens acima:","opcoes":["Apenas o item I está correto.","Apenas o item II está correto.","Apenas os itens I e III estão corretos.","Todos os itens estão corretos."],"correta":3,"explicacao":"Gabarito: <strong>Todos os itens estão corretos.</strong>.","banca":"AMEOSC","ano":2018,"temas_relacionados":["encontrosConsonantais","ditongos","tritongos","hiatos","silabas"]},{"id":375,"enunciado":"Sobre questões referentes aos aspectos sonoros da língua, assinale a alternativa INCORRETA:","opcoes":["Há hiato em todos os vocábulos a seguir retirados do texto: “razoavelmente”; “pior”; “atribuir” e “gloriosos”.","Constata-se, em todos os seguintes vocábulos: “procedido”; “certo”; “represálias”; “agirmos”; “castigados”; “voluntariamente” e “perceber” retirados do texto, a ocorrência de encontro consonantal.","Dentre os vocábulos: “ninguém”; “muito”; “boicotando”; “remédio”; “senão”; “quando” e “ajudou” há um total de quatro ditongos nasais.","Nos vocábulos “conta”; “disso”; “compreendemos”; “queremos”; “orgulhosos” e “porque”, há a ocorrência de dígrafo.","Os ditongos presentes nos vocábulos “pouco”; “muito”; “boicotando” e “fui” são classificados todos como decrescentes."],"correta":1,"explicacao":"Gabarito: <strong>Constata-se, em todos os seguintes vocábulos: “procedido”; “certo”; “represálias”; “agirmos”; “castigados”; “voluntariamente” e “perceber” retirados do texto, a ocorrência de encontro consonantal.</strong>.","banca":"CONTEMAX","ano":2020,"temas_relacionados":["encontrosConsonantais","ditongos","hiatos","digrafos"]},{"id":392,"enunciado":"Considere os itens a seguir: I – Autonomia é exemplo de ditongo crescente. II – Freire é exemplo de encontro consonantal perfeito. III – Crescente é exemplo de encontro consonantal misto. Está CORRETO o que se afirma em:","opcoes":["I e II, apenas.","I e III, apenas.","II e III, apenas.","Nenhuma das alternativas."],"correta":2,"explicacao":"Gabarito: <strong>II e III, apenas.</strong>.","banca":"Instituto Excelência","ano":2019,"temas_relacionados":["encontrosConsonantais","ditongos"]},{"id":394,"enunciado":"Há, respectivamente, encontro consonantal e encontro vocálico em:","opcoes":["“Correndo” e “suas”.","“Arredores” e “criação”.","\"Tinha” e “ficou”.","“Flor” e “avisou”."],"correta":3,"explicacao":"Gabarito: <strong>“Flor” e “avisou”.</strong>.","banca":"Fundação de Apoio à UNESPAR","ano":2018,"temas_relacionados":["encontrosConsonantais","ditongos","hiatos","tritongos"]},{"id":399,"enunciado":"Sobre os encontros vocálicos e consonantais, analise: I. Há encontro consonantal em “vinho” (linha 1); II. A palavra “contesta” (linha 3) possui um hiato e um encontro consonantal, respectivamente; III. Em “evidência” (linha 14) há um ditongo. Dos itens acima:","opcoes":["Apenas o item I está correto.","Apenas o item III está correto.","Apenas os itens II e III estão corretos.","Todos os itens estão corretos."],"correta":1,"explicacao":"Gabarito: <strong>Apenas o item III está correto.</strong>.","banca":"AMEOSC","ano":2019,"temas_relacionados":["encontrosConsonantais","ditongos","hiatos"]},{"id":402,"enunciado":"Com base nos encontros vocálicos e consonantais, analise: I- Há encontro consonantal em “pesados” (linha 4); II- Há hiato em “saúde” (linha 3); III- As letras destacadas em “concluiu” (linha 2) caracterizam um encontro consonantal. Dos itens acima:","opcoes":["Apenas o item II está correto.","Apenas os itens I e III estão corretos.","Aos os itens II e III estão corretos.","Todos os itens estão corretos."],"correta":2,"explicacao":"Gabarito: <strong>Aos os itens II e III estão corretos.</strong>.","banca":"AMEOSC","ano":2019,"temas_relacionados":["encontrosConsonantais","hiatos"]},{"id":411,"enunciado":"Quanto á pronúncia dos verbos, assinale (V) verdadeiro ou (F) falso e marque a alternativa correta: ( ) Os verbos terminados em -echar, -egar, -ejar, -elhar e -exar conservam o e tônico fechado em todas as pessoas, com exceção de flechar, mechar e invejar. ( ) Nos verbos que trazem ditongo, a vogal, sempre fechada, e a semivogal devem ser muito bem pronunciadas. Exceções: aboiar, apoiar e boiar. ( ) Os verbos que trazem hiato possuem as formas rizotônicas sem acento, na segunda vogal do hiato. ( ) Os verbos cujos radicais terminam em encontro consonantal têm, nas formas rizotônicas, o acento na vogal imediatamente anterior ao encontro consonantal. ( ) Todo verbo que tenha um substantivo proparoxítono correspondente começa a ser conjugado numa forma paroxítona.","opcoes":["V – V – V – V – F.","V – V – F – V – V.","c) V – V – V – F – V.","V – V – V – V – V."],"correta":0,"explicacao":"Gabarito: <strong>V – V – V – V – F.</strong>.","banca":"MSConcursos","ano":2020,"temas_relacionados":["encontrosConsonantais","ditongos","hiatos","proparoxitonas","paroxitonas"]},{"id":421,"enunciado":"Assinale a alternativa correta referente aos encontros das letras e dos sons que ocorrem na língua portuguesa.","opcoes":["Na palavra “pesquisa” há, respectivamente, um encontro consonantal e um ditongo.","Em “crescente” há, respectivamente, três encontros consonantais: “cr”, “sc” e “nt”.","Há dígrafo na palavra “negro”.","Há dígrafo na palavra “empreender”.","Há dígrafo na palavra “igualdade”."],"correta":3,"explicacao":"Gabarito: <strong>Há dígrafo na palavra “empreender”.</strong>.","banca":"INSTITUTO AOCP","ano":2016,"temas_relacionados":["encontrosConsonantais","digrafos"]},{"id":428,"enunciado":"Avalie as afirmações que seguem sobre determinados vocábulos do texto: I. Na palavra trabalho, há um encontro consonantal imperfeito e um dígrafo vocálico. II. Em sincronia, evidencia-se um dígrafo, assim como em resultante. III. No vocábulo Ademais, ocorre um ditongo crescente. IV. Na palavra comportamental, há menos fonemas que letras. Quais estão corretas?","opcoes":["Apenas I e III.","Apenas II e IV.","Apenas I, II e III.","Apenas II, III e IV.","I, II, III e IV."],"correta":1,"explicacao":"Gabarito: <strong>Apenas II e IV.</strong>.","banca":"FUNDATEC","ano":2021,"temas_relacionados":["encontrosConsonantais","ditongos","digrafos","fonemas"]},{"id":442,"enunciado":"Analise as assertivas sobre palavras retiradas do texto a seguir e marque (V) se for verdadeira, ou (F) se for falsa: ( ) Em “chegar”, “milhões” e “ocorrência” há dígrafo. ( ) Em “considerada”, “risco” e “resultados” há encontro consonantal. ( ) Em “mais”, “especialistas” e “outra” há hiato. ( ) Em “relacionado”, “causa” e “cientistas” há ditongo. A CORRETA sequência de preenchimento, de cima para baixo é:","opcoes":["V – V – V – V.","V – F – F – V.","F – F – V – F.","V – V – F – F.","F – V – V – F."],"correta":3,"explicacao":"Gabarito: <strong>V – V – F – F.</strong>.","banca":"UNESPAR","ano":2019,"temas_relacionados":["encontrosConsonantais","ditongos","hiatos","digrafos"]},{"id":443,"enunciado":"Assinale a alternativa que apresenta, respectivamente, um ditongo decrescente, um encontro consonantal e um dígrafo.","opcoes":["“sociais” (L.2), “onde” (L.2), “pessoa” (L.10)","“aproveite” (L.25), “proporciona” (L. 15), “tem” (L.5)","“pessoas” (L.23), “tempo” (L.7), “dessa” (L.24)","“podem” (L.3), “conectados” (L.1), “histórias” (L.24)"],"correta":3,"explicacao":"Gabarito: <strong>“podem” (L.3), “conectados” (L.1), “histórias” (L.24)</strong>.","banca":"Crescer Concursos","ano":2016,"temas_relacionados":["encontrosConsonantais","ditongos","digrafos"]},{"id":446,"enunciado":"Na palavra passo as letras em destaque são classificadas como","opcoes":["encontro consonantal.","ditongo.","hiato.","dígrafo."],"correta":3,"explicacao":"Gabarito: <strong>dígrafo.</strong>.","banca":"CONSESP","ano":2018,"temas_relacionados":["encontrosConsonantais","digrafos"]},{"id":461,"enunciado":"Analise as palavras abaixo quanto a presença de Encontros Vocálicos, Encontros Consonantais e Dígrafos: QUAISQUER – GLICOSE – MOSQUITO – GRAVIDADE - PISCINA Sobre essas palavras, é CORRETO afirmar:","opcoes":["Há presença de Tritongo e Ditongo na palavra “quaisquer”.","Há um exemplo de Ditongo e dois Dígrafos.","“Glicose” e “gravidade” contêm Dígrafos.","Apenas a palavra “mosquito” é exemplo de Encontro Consonantal.","Nenhuma delas apresenta Hiato ou Ditongo."],"correta":4,"explicacao":"Gabarito: <strong>Nenhuma delas apresenta Hiato ou Ditongo.</strong>.","banca":"FAEPESUL","ano":2016,"temas_relacionados":["encontrosConsonantais","ditongos","hiatos","digrafos","tritongos"]},{"id":492,"enunciado":"Identifique os fenômenos fonéticos que ocorrem nos vocábulos da Coluna 2, relacionando-os aos seus respectivos nomes, constantes na Coluna 1. Coluna 1 1. Dígrafo. 2. Encontro consonantal. 3. Hiato. 4. Ditongo. Coluna 2 ( ) necessidades ( ) chances ( ) concepção ( ) oasis ( ) perfeito A ordem correta de preenchimento dos parênteses, de cima para baixo, é:","opcoes":["1 – 2 – 2 – 3 – 4.","1 – 1 – 2 – 3 – 4.","2 – 2 – 1 – 4 – 3.","4 – 1 – 1 – 3 – 2.","3 – 4 – 2 – 1 – 1."],"correta":1,"explicacao":"Gabarito: <strong>1 – 1 – 2 – 3 – 4.</strong>.","banca":"FUNDATEC","ano":2018,"temas_relacionados":["encontrosConsonantais","ditongos","hiatos","digrafos"]},{"id":500,"enunciado":"Considere as seguintes palavras retiradas do texto e, sobre elas, assinale a alternativa INCORRETA. - Titanossauro. - Descarrilamento. - Esqueletos.","opcoes":["A separação silábica dessas palavras é: ti-ta-nos-sau-ro / des-car-ri-la-men-to / es-que-le-tos.","As três palavras apresentam dígrafos consonantais.","Apenas duas das palavras apresentam encontro consonantal.","As três palavras têm a penúltima sílaba tônica; ou seja, são paroxítonas.","As três palavras apresentam ditongo oral."],"correta":4,"explicacao":"Gabarito: <strong>As três palavras apresentam ditongo oral.</strong>.","banca":"FUNDATEC","ano":2019,"temas_relacionados":["encontrosConsonantais","ditongos","digrafos","silabas","paroxitonas","tonicidade"]},{"id":507,"enunciado":"Considerando o conceito de encontros vocálicos e encontros consonantais, assinale, dentre as orações a seguir, aquela que apresenta um hiato.","opcoes":["“Não conheço melhor ofício, mormente se a gente se mete por bairros excêntricos”.","“Dois episódios, porém, me deram a medida do que valho, quando rumino”.","“[...] o leitor e eu fomos os únicos que os comparamos”.","“[...] lembrei-me não sei como o incêndio do club dos Tenentes do Diabo”.","“Pegou em si e no livro da escrituração e correu pela escada abaixo”."],"correta":3,"explicacao":"Gabarito: <strong>“[...] lembrei-me não sei como o incêndio do club dos Tenentes do Diabo”.</strong>.","temas_relacionados":["encontrosConsonantais","hiatos","ditongos","tritongos"]},{"id":509,"enunciado":"Acerca dos dígrafos e dos encontros vocálicos e consonantais na Língua Portuguesa, assinale a alternativa que apresenta palavras com: dígrafo nasal e encontro vocálico; encontro vocálico e encontro consonantal; encontro consonantal e encontro vocálico, respectivamente:","opcoes":["Dançar; sobre; verso.","Chuva; escalar; poema.","Caminho; situações; fortaleceu.","Mundo; fosse; compartilhar.","Dinheiro; outros; venceu."],"correta":4,"explicacao":"Gabarito: <strong>Dinheiro; outros; venceu.</strong>.","banca":"AOCP","ano":2017,"temas_relacionados":["encontrosConsonantais","digrafos","ditongos","hiatos","tritongos"]},{"id":510,"enunciado":"Sobre a palavra “processo” (linha 1), assinale a alternativa CORRETA:","opcoes":["Não possui encontro consonantal.","Não possui encontro vocálico.","Não possui encontro vocálico, tampouco dígrafo.","Possui encontro vocálico e não possui encontro consonantal."],"correta":1,"explicacao":"Gabarito: <strong>Não possui encontro vocálico.</strong>.","banca":"GUALIMP","ano":2019,"temas_relacionados":["encontrosConsonantais","ditongos","hiatos","tritongos"]},{"id":520,"enunciado":"Assinale a alternativa correta.","opcoes":["Em “nasce”, há encontro consonantal.","Em “sempre”, há dígrafo.","Em “outro”, há hiato.","Em “queria”, há ditongo crescente.","Em “trabalho”, o “h” não provoca interferência sonora, tal qual em “horário”."],"correta":1,"explicacao":"Gabarito: <strong>Em “sempre”, há dígrafo.</strong>.","banca":"INSTITUTO AOCP","ano":2017,"temas_relacionados":["encontrosConsonantais","digrafos"]},{"id":527,"enunciado":"Assinale a alternativa que apresenta uma palavra com um dígrafo consonantal (duas letras que representam um fonema consonantal) e um ditongo (dois fonemas vocálicos pronunciados na mesma sílaba).","opcoes":["Angústias.","Necessário.","Verdadeira.","Passado."],"correta":1,"explicacao":"Gabarito: <strong>Necessário.</strong>.","banca":"INSTITUTO AOCP","ano":2019,"temas_relacionados":["encontrosConsonantais","ditongos","digrafos","silabas","fonemas"]},{"id":538,"enunciado":"Avalie as afirmações acerca das palavras presentes nos balões. I. EXPLICAR é oxítona. II. PIRAMBABA é polissílaba. III. PESSOA é formada por um ditongo. IV. CO-I-SAS apresenta a separação de sílabas de forma correta da palavra \"coisas\". V. ESTOU contém um encontro consonantal e um encontro vocálico. Está correto apenas o que se afirma em","opcoes":["I, II e V.","I e II.","II, III e IV","III, IV e V."],"correta":0,"explicacao":"Gabarito: <strong>I, II e V.</strong>.","banca":"FCM","ano":2019,"temas_relacionados":["encontrosConsonantais","ditongos","silabas","hiatos","tritongos","oxitonas"]},{"id":543,"enunciado":"Referente aos aspectos fonológicos, assinale a alternativa correta.","opcoes":["Em “geração” e “precisarem”, a letras destacadas representam o fonema /s/.","Em “impregnam”, destaca-se um encontro consonantal perfeito e um ditongo nasal.","Em “afetuosa”, há quatro vogais e um hiato.","Em “encerra”, as vogais “e” possuem a mesma pronúncia, evidenciando a mesma abertura vocálica.","Em “Sobrevieram”, identifica-se um hiato, um encontro consonantal e dois ditongos."],"correta":1,"explicacao":"Gabarito: <strong>Em “impregnam”, destaca-se um encontro consonantal perfeito e um ditongo nasal.</strong>.","banca":"INSTITUTO AOCP","ano":2018,"temas_relacionados":["encontrosConsonantais","ditongos"]},{"id":548,"enunciado":"São palavras que, respectivamente, apresentam encontro vocálico e encontro consonantal:","opcoes":["Provavelmente – Marido","Opinião – Desconsolado.","Mulherzinha – Panela.","Ponta – Aconteceu."],"correta":1,"explicacao":"Gabarito: <strong>Opinião – Desconsolado.</strong>.","banca":"AMEOSC","ano":2019,"temas_relacionados":["encontrosConsonantais","ditongos","hiatos","tritongos"]},{"id":568,"enunciado":"De acordo com as regras vigentes no sistema ortográfico da língua portuguesa, a palavra “viúvo”, presente no texto, apresenta:","opcoes":["ditongo","hiato","tritongo","encontro consonantal","desinência modo-temporal"],"correta":1,"explicacao":"Gabarito: <strong>hiato</strong>.","banca":"FACET Concursos","ano":2018,"temas_relacionados":["encontrosConsonantais","hiatos"]},{"id":573,"enunciado":"Com base em seus conhecimentos linguísticos, assinale a alternativa em que se indica, CORRRETAMENTE, o elemento em destaque.","opcoes":["preferia – ditongo.","sair – hiato.","conceito – dígrafo.","esquina – encontro consonantal."],"correta":1,"explicacao":"Gabarito: <strong>sair – hiato.</strong>.","banca":"IBFC","ano":2018,"temas_relacionados":["encontrosConsonantais","hiatos"]},{"id":577,"enunciado":"Analise as afirmativas a seguir: I – Encontro consonantal é a junção de sons consonantais simultâneos dentro da palavra. Pode ser classificado de acordo com o modo como se apresenta. II – Podemos observar encontros consonantais perfeitos nas palavras “pequenos” e “lampejos”. III – Podemos observar encontros consonantais imperfeitos nas palavras “dentro”, “mudanças”. IV – Encontro vocálico é a união de dois ou mais fonemas vocálicos em uma única sílaba ou em sílabas diferentes. V - Podemos observar ditongos decrescentes nas palavras “dias”, “silenciosas” e “mágoas”. Assinale a alternativa CORRETA:","opcoes":["Apenas as alternativas I e III estão corretas.","Apenas as alternativas I, III e IV estão corretas.","Apenas as alternativas I, III, IV e V estão corretas.","Apenas as alternativas I, II, III, IV e V estão corretas."],"correta":1,"explicacao":"Gabarito: <strong>Apenas as alternativas I, III e IV estão corretas.</strong>.","banca":"Orhion Consultoria","ano":2018,"temas_relacionados":["encontrosConsonantais","ditongos","silabas","hiatos","tritongos","fonemas"]},{"id":578,"enunciado":"A respeito das palavras abandono, profissional, país e quando, assinale a alternativa correta.","opcoes":["Em quando, há encontro consonantal; em país, há hiato; em profissional, há encontro consonantal e dígrafo; em abandono, há encontro consonantal.","Em profissional, há 2 dígrafos; em abandono, há encontro consonantal; em quando, há ditongo decrescente; em país, há hiato.","Em abandono, há dígrafo; em profissional, há encontro consonantal e dígrafo; em país, há hiato; em quando, há ditongo crescente.","Em país, há ditongo crescente; em quando, há ditongo crescente; em abandono, há encontro consonantal; em profissional, há dígrafo.","Em profissional, há 2 encontros consonantais; em país, há hiato; em quando, há hiato; em abandono, há dígrafo."],"correta":2,"explicacao":"Gabarito: <strong>Em abandono, há dígrafo; em profissional, há encontro consonantal e dígrafo; em país, há hiato; em quando, há ditongo crescente.</strong>.","banca":"INSTITUTO AOCP","ano":2018,"temas_relacionados":["encontrosConsonantais","ditongos","hiatos","digrafos"]},{"id":581,"enunciado":"Considere as seguintes afirmações sobre a relação entre sons, pronúncia e grafia. I - Apresentam ditongo nasal as palavras homem (I. 01), criam (I. 06) e antigos (l. 21). II - Apresentam ditongo oral nas suas formas plurais as palavras animal (I. 01), fácil (l. 04) e nível (I. 06). III- Apresentam encontro consonantal as palavras excesso (I. 14), estilhaçamento (I. 14) e fluxo (I. 15). Quais estão corretas?","opcoes":["Apenas I.","Apenas II.","Apenas III.","Apenas I e II.","Apenas I e III."],"correta":1,"explicacao":"Gabarito: <strong>Apenas II.</strong>.","banca":"FAURGS","ano":2017,"temas_relacionados":["encontrosConsonantais","ditongos","ortografia"]},{"id":587,"enunciado":"Marque a afirmação incorreta.","opcoes":["Em: “profissionais”, temos exemplo de: encontro consonantal; dífono; hiato e ditongo decrescente oral.","O trecho: “Obrigado pela atenção e vamos à aula de hoje.”- enuncia discurso direto proferido por um ser do sexo masculino.","A palavra: “medíocres” é proparoxítona, estruturada com hiato e encontro consonantal.","No segmento: “o velho professor perdeu a paciência e decidiu tomar uma atitude mais drástica.” – temos exemplo de coordenação sindética aditiva.","Em: “há muitos que não lembram...” – temos uma oração construída com verbo impessoal e sujeito inexistente."],"correta":0,"explicacao":"Gabarito: <strong>Em: “profissionais”, temos exemplo de: encontro consonantal; dífono; hiato e ditongo decrescente oral.</strong>.","banca":"CONCEPÇÃO","ano":2012,"temas_relacionados":["encontrosConsonantais","ditongos","hiatos","proparoxitonas"]},{"id":598,"enunciado":"Acerca da palavra “administração”, quanto aos encontros vocálicos e consonantais, ela apresenta","opcoes":["3 encontros consonantais duplos e 1 ditongo.","3 encontros consonantais duplos e 1 dígrafo.","2 encontros consonantais duplos e 1 triplo e 1 dígrafo.","1 encontro consonantal duplo e 1 triplo e 1 ditongo.","2 encontros consonantais duplos e 2 triplos e 1 dígrafo."],"correta":3,"explicacao":"Gabarito: <strong>1 encontro consonantal duplo e 1 triplo e 1 ditongo.</strong>.","banca":"IF-CE","ano":2016,"temas_relacionados":["encontrosConsonantais","ditongos"]},{"id":606,"enunciado":"Quanto à classificação dos sons linguísticos, em “Alguns desistiram” (linha 8), há exatamente:","opcoes":["1 (um) ditongo e 1 (um) dígrafo.","1 (um) encontro consonantal e 2 (dois) dígrafos.","1 (um) encontro consonantal e (1) dígrafo.","2 (dois) dígrafos."],"correta":3,"explicacao":"Gabarito: <strong>2 (dois) dígrafos.</strong>.","banca":"AMEOSC","ano":2016,"temas_relacionados":["encontrosConsonantais","digrafos"]},{"id":628,"enunciado":"A respeito do fragmento Água parada e limpa são ambientes ideais para a fêmea do mosquito da dengue depositar seus ovos, todas as alternativas estão corretas, EXCETO:","opcoes":["Há palavras que contêm ditongos.","Há palavras que contêm tritongos.","Há palavras que contêm hiatos.","Há palavras que contêm encontros consonantais.","Há palavras que contêm dígrafos."],"correta":1,"explicacao":"Gabarito: <strong>Há palavras que contêm tritongos.</strong>.","banca":"UFCG","ano":2016,"temas_relacionados":["encontrosConsonantais","ditongos","tritongos","hiatos","digrafos"]},{"id":645,"enunciado":"Assinale a alternativa incorreta:","opcoes":["“sofrendo” tem 1 encontro consonantal e 1 dígrafo.","“noitinha” tem 1 ditongo e 1 dígrafo.","“descuido” tem 1 encontro consonantal e um hiato.","“esperneava” tem dois encontros consonantal e 1 hiato."],"correta":2,"explicacao":"Gabarito: <strong>“descuido” tem 1 encontro consonantal e um hiato.</strong>.","banca":"EXATUS-PR","ano":2015,"temas_relacionados":["encontrosConsonantais","ditongos","hiatos","digrafos"]},{"id":647,"enunciado":"Analise as afirmativas e em seguida assinale a incorreta:","opcoes":["“mundo\" tem 5 letras 4 fonemas e um dígrafo.","“criança\" tem 7 letras, 6 fonemas, 1 encontro consonantal, 1 hiato e 1 dígrafo.","“guarda\" tem 6 letras, 6 fonemas, 1 hiato, 1 encontro consonantal.","“glória\" tem 6 letras, 6 fonemas, 1 encontro consonantal e 1 ditongo."],"correta":2,"explicacao":"Gabarito: <strong>“guarda\" tem 6 letras, 6 fonemas, 1 hiato, 1 encontro consonantal.</strong>.","banca":"EXATUS-PR","ano":2015,"temas_relacionados":["encontrosConsonantais","ditongos","hiatos","digrafos","fonemas"]},{"id":658,"enunciado":"Qual opção abaixo apresenta na sequência de palavras um encontro consonantal perfeito, um encontro consonantal imperfeito, um encontro vocálico e um dígrafo vocálico?","opcoes":["Prato, pacto, raiz, lenha.","Absoluto, crescer, limpo, Paraguai.","Quando, excerto, ritmo, Saara.","Crítica, afta, saguão, tenente.","Assado, clima, abstinência, guerra."],"correta":3,"explicacao":"Gabarito: <strong>Crítica, afta, saguão, tenente.</strong>.","banca":"COPEVE-UFAL","ano":2011,"temas_relacionados":["encontrosConsonantais","digrafos","ditongos","hiatos","tritongos"]},{"id":664,"enunciado":"Assinale a alternativa que apresenta, na sequência, palavras que tenham um tritongo, um encontro consonantal e um dígrafo.","opcoes":["Queijo – porta – chave.","Marinheiro – porta – iguais.","Iguais – tampa – marinheiro.","Quais – atleta – tampa..","Queijo – tampa – chave."],"correta":3,"explicacao":"Gabarito: <strong>Quais – atleta – tampa..</strong>.","banca":"INSTITUTO AOCP","ano":2015,"temas_relacionados":["encontrosConsonantais","tritongos","digrafos"]},{"id":666,"enunciado":"Em relação à palavra EDUCAÇÃO, apresentada por Rubem Alves, temos: Imagem associada para resolução da questão","opcoes":["Um hiato.","Um ditongo.","Um tritongo.","Um encontro consonantal."],"correta":1,"explicacao":"Gabarito: <strong>Um ditongo.</strong>.","banca":"IOBV","ano":2015,"temas_relacionados":["encontrosConsonantais","ditongos"]},{"id":670,"enunciado":"Leia as palavras, a seguir, retiradas do texto, e indique (EV) para Encontro Vocálico e (EC) para Encontro Consonantal (em destaque a silabar-referência para responder a questão): ( ) Novembro. ( ) Entregues. ( ) Inadequado. ( ) Salário. ( ) Direito. A sequência CORRETA, de cima para baixo, é:","opcoes":["EV – EC – EV – EV – EV.","EC – EV – EV – EC – EC.","EC – EV – EV – EC – EV.","EC – EC – EV – EV – EV."],"correta":3,"explicacao":"Gabarito: <strong>EC – EC – EV – EV – EV.</strong>.","banca":"FAFIPA","ano":2015,"temas_relacionados":["encontrosConsonantais","silabas","ditongos","hiatos","tritongos"]},{"id":679,"enunciado":"Considere as seguintes informações sobre as palavras do texto certas (C) ou erradas (E): As palavras cigarro (linha 45) e dinheiro (linha 63) possuem encontro consonantal, o que faz com que tenham numero de fonemas maior do que de letras, II. A pronuncia da letra X nas palavras lixeira (linha 47) e luxo (linha 74) faz com que as mesmas tenham um número de fonemas maior do que o de letras. III. Na palavra classifiquei (linha 4) ocorre apenas rim dígrafo. IV. As palavras classifiquei (linha 4) e amassou (linha 45) não possuem um mesmo tipo de encontro vocálico. Assinale a sequência correta","opcoes":["C-C-C-C.","E-E-E-E.","C-E-E-C","C-E-C-E","E-C-E-C."],"correta":1,"explicacao":"Gabarito: <strong>E-E-E-E.</strong>.","banca":"PC-RS","ano":2009,"temas_relacionados":["encontrosConsonantais","digrafos","ditongos","hiatos","tritongos","fonemas"]},{"id":691,"enunciado":"Considerando os encontros consonantais e vocálicos, dígrafos e divisão silábica, marque a(s) afirmativa(s) correta(s). I) Os termos do texto I “repugnância” (3º§) e “estigma” (4º§) apresentam encontro consonantal, cuja separação silábica é “re-pug- nân-cia” e “es-tig-ma” II) A palavra “sessão” do texto II (1º§) apresenta um dígrafo e pode ser escrita “sesção”, mantendo-se o mesmo sentido no texto. III) A palavra “cláusula” (4º §) do texto II apresenta um ditongo decrescente e “ministério” do texto II (1º§) apresenta um ditongo crescente. Está(ão) correta(s):","opcoes":["I e II.","I e III.","III.","II e III.","II."],"correta":1,"explicacao":"Gabarito: <strong>I e III.</strong>.","banca":"UFCG","ano":2008,"temas_relacionados":["encontrosConsonantais","ditongos","digrafos","silabas"]},{"id":694,"enunciado":"As alternativas a seguir apresentam vocábulos (retirados do texto) que contêm, respectivamente: um hiato, um encontro consonantal e um dígrafo, à exceção de","opcoes":["sociedade – impactos – questões","biótico – obras – barragens","construída – tecnológicas – ecossistemas","ideal – constatações – engenharia","prévia – pressões – fragilidade"],"correta":4,"explicacao":"Gabarito: <strong>prévia – pressões – fragilidade</strong>.","banca":"FUNDATEC","ano":2010,"temas_relacionados":["encontrosConsonantais","hiatos","digrafos"]},{"id":697,"enunciado":"Sobre a identificação de encontros consonantais, encontros vocálicos e dígrafos é CORRETO afirmar que","opcoes":["há dígrafo nas seguintes palavras: distintos, presidente e imposto.","há ditongo nas seguintes palavras: quando, duas e oposição.","há hiato nas seguintes palavras: negociação, muito e imediato.","há encontro consonantal nas seguintes palavras: conquista, objetivo e aumentos.","há tritongo nas seguintes palavras: imediatamente, titubeante e população."],"correta":0,"explicacao":"Gabarito: <strong>há dígrafo nas seguintes palavras: distintos, presidente e imposto.</strong>.","banca":"FUNRIO","ano":2013,"temas_relacionados":["encontrosConsonantais","digrafos","ditongos","hiatos","tritongos"]},{"id":715,"enunciado":"Essa espécie tem um desenvolvimento muito rápido - em apenas horas após a fecundação, a maioria dos órgãos dele já funciona. Para ter ideia, um peixe cresce em um dia o equivalente ao que um embrião humano demora um mês. Disponível em:(https://curtlink.com/wLo6rh7. Adaptado.) Assinale a opção que contenha somente palavras com encontros consonantais.","opcoes":["órgãos - essa","fecundação - equivalente","desenvolvimento - cresce","funciona - embrião"],"correta":2,"explicacao":"Gabarito: <strong>desenvolvimento - cresce</strong>.","banca":"AMEOSC","ano":2022,"temas_relacionados":["encontrosConsonantais"]},{"id":717,"enunciado":"Assinale a alternativa em que a palavra apresenta encontro consonantal perfeito.","opcoes":["Perplexos.","Revolta.","Roupagens.","Ecoou.","Debaixo."],"correta":0,"explicacao":"Gabarito: <strong>Perplexos.</strong>.","banca":"FAFIPA","ano":2025,"temas_relacionados":["encontrosConsonantais"]},{"id":719,"enunciado":"Analise as palavras abaixo e marque a alternativa que apresenta ocorrência de encontro consonantal:","opcoes":["você, faça, favor.","deu, me, zango.","desculpe, outro, perdoar.","bonita, Deus, com."],"correta":2,"explicacao":"Gabarito: <strong>desculpe, outro, perdoar.</strong>.","banca":"Aroeira","ano":2026,"temas_relacionados":["encontrosConsonantais"]},{"id":720,"enunciado":"Na lista abaixo, a alternativa em que todas as palavras apresentam encontro consonantal é:","opcoes":["prato, bloco, grito, clima.","chuva, chave, grama, classe.","freio, praia, caixa, muito.","massa, cabeça, caroço, cidade."],"correta":0,"explicacao":"Gabarito: <strong>prato, bloco, grito, clima.</strong>.","banca":"JVL Concursos","ano":2026,"temas_relacionados":["encontrosConsonantais"]},{"id":721,"enunciado":"Marque a alternativa com uma palavra escrita com um encontro consonantal e um hiato; e uma palavra escrita com ditongo nasal, respectivamente.","opcoes":["Escritor; não.","Atento; desinteressado.","Presumia; oração.","Fim; apropriar.","Infanticida; como."],"correta":2,"explicacao":"Gabarito: <strong>Presumia; oração.</strong>.","banca":"MS Consultoria","ano":2023,"temas_relacionados":["encontrosConsonantais","ditongos","hiatos"]},{"id":722,"enunciado":"Assinale a alternativa em que as letras sublinhadas nas palavras são classificadas como encontro consonantal.","opcoes":["Humilhante, grato, aspirina.","Humildes, nobres, carga.","Terrível, prática, onde.","Exemplo, tensão, isso.","Grega, barriga, alma."],"correta":1,"explicacao":"Gabarito: <strong>Humildes, nobres, carga.</strong>.","banca":"FAFIPA","ano":2025,"temas_relacionados":["encontrosConsonantais"]},{"id":723,"enunciado":"Quando duas consoantes se encontram e os dois sons são pronunciados, temos um encontro consonantal. Aponte a alternativa abaixo em que isso ocorre.","opcoes":["Luva.","Água.","Caneta.","Fio.","Livro."],"correta":4,"explicacao":"Gabarito: <strong>Livro.</strong>.","banca":"Instituto IACP","ano":2026,"temas_relacionados":["encontrosConsonantais"]},{"id":724,"enunciado":"Qual das palavras abaixo apresenta encontro consonantal?","opcoes":["Manobras.","Férias.","Paradas.","Direção.","Velocidade."],"correta":0,"explicacao":"Gabarito: <strong>Manobras.</strong>.","banca":"FUNDATEC","ano":2026,"temas_relacionados":["encontrosConsonantais"]},{"id":725,"enunciado":"Considere, entre as palavras retiradas do texto, a que apresenta, somente, encontro consonantal disjunto:","opcoes":["Integração.","Privacidade.","Reorganiza.","Extrapolam."],"correta":2,"explicacao":"Gabarito: <strong>Reorganiza.</strong>.","banca":"Gama Consult","ano":2026,"temas_relacionados":["encontrosConsonantais"]},{"id":727,"enunciado":"Assinale a alternativa que apresenta uma palavra com encontro consonantal como em “blusa”","opcoes":["Água.","Palácio.","Guaraná.","Precioso.","Divino."],"correta":3,"explicacao":"Gabarito: <strong>Precioso.</strong>.","banca":"FUNDATEC","ano":2025,"temas_relacionados":["encontrosConsonantais"]},{"id":728,"enunciado":"Ao transcrevermos fonologicamente as palavras abaixo, a letra X se confundirá com encontro consonantal em:","opcoes":["Excelente.","Exame.","Enxame.","Prolixo."],"correta":3,"explicacao":"Gabarito: <strong>Prolixo.</strong>.","banca":"OBJETIVA","ano":2025,"temas_relacionados":["encontrosConsonantais"]},{"id":730,"enunciado":"A palavra interpretativismo, presente na oração “O positivismo e o interpretativismo são as duas principais tradições no desenvolvimento da pesquisa social”, caracteriza‑se por apresentar três encontros consonantais, sendo dois imperfeitos e um perfeito.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["encontrosConsonantais"]},{"id":731,"enunciado":"Marque a alternativa em que todas as palavras apresentam encontros consonantais:","opcoes":["tudo, forma, como.","plantas, contra, pragas.","jardins, tipos, seres.","causar, então, podem."],"correta":1,"explicacao":"Gabarito: <strong>plantas, contra, pragas.</strong>.","banca":"Aroeira","ano":2025,"temas_relacionados":["encontrosConsonantais"]},{"id":732,"enunciado":"Assinalar a alternativa em que há um encontro consonantal.","opcoes":["Rolha.","Cortiça.","Vinho.","Nativa."],"correta":1,"explicacao":"Gabarito: <strong>Cortiça.</strong>.","banca":"OBJETIVA","ano":2025,"temas_relacionados":["encontrosConsonantais"]},{"id":733,"enunciado":"Assinale a alternativa, onde não temos encontro consonantal.","opcoes":["Bloco.","Atlas.","Pérola.","Bíblia."],"correta":2,"explicacao":"Gabarito: <strong>Pérola.</strong>.","banca":"MSConcursos","ano":2023,"temas_relacionados":["encontrosConsonantais"]},{"id":734,"enunciado":"Correspondem respectivamente a duas palavras com encontro consonantais:","opcoes":["Favorita – Até.","Trailer – Sinal.","Estava – Dirigindo.","Pela – Jogado.","Estrada – Vala."],"correta":2,"explicacao":"Gabarito: <strong>Estava – Dirigindo.</strong>.","banca":"ADVISE","ano":2023,"temas_relacionados":["encontrosConsonantais"]},{"id":735,"enunciado":"Assinale a alternativa a qual em ambas as palavras ocorrem encontros consonantais.","opcoes":["É – Um.","Primeiro – Assalto.","Eu – Falei.","Falei – Um.","Um – Eu."],"correta":1,"explicacao":"Gabarito: <strong>Primeiro – Assalto.</strong>.","banca":"ADVISE","ano":2023,"temas_relacionados":["encontrosConsonantais"]},{"id":736,"enunciado":"Pode-se afirmar que a palavra\" Enquanto\", no primeiro parágrafo do texto, contém:","opcoes":["um dígrafo.","um encontro consonantal.","um dígrafo e um encontro consonantal.","um encontro vocálico."],"correta":2,"explicacao":"Gabarito: <strong>um dígrafo e um encontro consonantal.</strong>.","banca":"Aroeira","ano":2023,"temas_relacionados":["encontrosConsonantais","digrafos"]},{"id":739,"enunciado":"Quando vamos ao supermercado, codificamos onde estacionamos o carro, mas quando entramos na loja, ocupamo-nos de outras coisas. Assinale a opção que contenha apenas encontro consonantal:","opcoes":["outras.","codificamos.","coisas.","supermercado.","estacionamos."],"correta":3,"explicacao":"Gabarito: <strong>supermercado.</strong>.","banca":"IASP","ano":2024,"temas_relacionados":["encontrosConsonantais"]},{"id":740,"enunciado":"Assinale a alternativa que apresenta uma palavra em que ocorre um encontro consonantal.","opcoes":["Barulho.","Carroça.","Passeio.","Pássaros.","Clareira."],"correta":4,"explicacao":"Gabarito: <strong>Clareira.</strong>.","banca":"Instituto Avalia","ano":2025,"temas_relacionados":["encontrosConsonantais"]},{"id":742,"enunciado":"Uma dura fase marcada por conflitos e dificuldades. É assim que especialistas resumem a forma como o envelhecimento dos pais é encarado diversas vezes. A opção que contém apenas encontros consonantais é:","opcoes":["conflitos − fase","diversas − especialistas","marcada − forma","dificuldades − resumem","vezes − assim"],"correta":2,"explicacao":"Gabarito: <strong>marcada − forma</strong>.","banca":"IASP","ano":2024,"temas_relacionados":["encontrosConsonantais"]},{"id":750,"enunciado":"A palavra “obtidos”, sublinhada no último parágrafo, é, quanto à fonologia, um exemplo de palavra com:","opcoes":["Dígrafo.","Tritongo.","Encontro consonantal.","Hiato."],"correta":2,"explicacao":"Gabarito: <strong>Encontro consonantal.</strong>.","banca":"OBJETIVA","ano":2024,"temas_relacionados":["encontrosConsonantais"]},{"id":751,"enunciado":"Aludindo-se a encontros consonantais, marque a alternativa indevida.","opcoes":["Atrás.","Creme.","Subdelegado.","Café."],"correta":3,"explicacao":"Gabarito: <strong>Café.</strong>.","banca":"MSConcursos","ano":2024,"temas_relacionados":["encontrosConsonantais"]},{"id":752,"enunciado":"No texto, há um exemplo de encontro consonantal na palavra:","opcoes":["raízes.","México.","cidade.","clavícula.","popular."],"correta":3,"explicacao":"Gabarito: <strong>clavícula.</strong>.","banca":"Fundação FAPEC","ano":2025,"temas_relacionados":["encontrosConsonantais"]},{"id":753,"enunciado":"Assinale a alternativa em que há um encontro consonantal:","opcoes":["“sociedade”","“Quem”","“profissional”","“Amador”"],"correta":2,"explicacao":"Gabarito: <strong>“profissional”</strong>.","banca":"Itame","ano":2025,"temas_relacionados":["encontrosConsonantais"]},{"id":759,"enunciado":"Considerando a fonética de palavras retiradas do texto, analise as seguintes assertivas e assinale V, se verdadeiras, ou F, se falsas. ( ) Na palavra “estresse”, há um dígrafo. ( ) A palavra “despertador” tem o mesmo número de letras e fonemas. ( ) É possível identificar encontro consonantal em “psicólogo”. A ordem correta de preenchimento dos parênteses, de cima para baixo, é:","opcoes":["F – F – V.","F – V – V.","F – V – F.","V – V – V.","V – F – F."],"correta":3,"explicacao":"Gabarito: <strong>V – V – V.</strong>.","banca":"FUNDATEC","ano":2025,"temas_relacionados":["encontrosConsonantais","digrafos","fonemas"]},{"id":760,"enunciado":"Qual das alternativas abaixo apresenta uma palavra com encontro consonantal?","opcoes":["Litros.","Minutos.","Automóvel.","Medidas."],"correta":0,"explicacao":"Gabarito: <strong>Litros.</strong>.","banca":"Prefeitura de Catas Altas - MG","ano":2025,"temas_relacionados":["encontrosConsonantais"]},{"id":762,"enunciado":"Assinale a alternativa onde ocorre respectivamente um encontro consonantal perfeito e um imperfeito:","opcoes":["praga e tetra.","ritmo e afta.","blusa e pacto.","rapto e brasa.","acne e brejo."],"correta":2,"explicacao":"Gabarito: <strong>blusa e pacto.</strong>.","banca":"IBADE","ano":2025,"temas_relacionados":["encontrosConsonantais"]},{"id":766,"enunciado":"Qual das palavras abaixo apresenta um encontro consonantal (duas ou mais consoantes juntas na mesma sílaba)?","opcoes":["Aquecimento.","Estudo.","Inundação.","Clima.","Aumento."],"correta":3,"explicacao":"Gabarito: <strong>Clima.</strong>.","banca":"FUNDATEC","ano":2025,"temas_relacionados":["encontrosConsonantais","silabas"]},{"id":768,"enunciado":"Qual alternativa apresenta uma palavra que tem encontro consonantal?","opcoes":["Vela.","Elas.","Paris.","Livre.","Maior."],"correta":3,"explicacao":"Gabarito: <strong>Livre.</strong>.","banca":"FUNDATEC","ano":2024,"temas_relacionados":["encontrosConsonantais"]},{"id":778,"enunciado":"No fragmento “Às vezes dou a minha opinião”, o termo “dou”:","opcoes":["é um exemplo de encontro consonantal, pois há um ditongo, assim como acontece na palavra “baixo”.","é um exemplo de encontro vocálico, pois há um hiato, assim como acontece na palavra “saúde”.","é um exemplo de encontro vocálico, pois há um tritongo, assim como acontece na palavra “água”.","é um exemplo de encontro vocálico, pois há um ditongo, assim como acontece na palavra “lousa”.","é um exemplo de encontro consonantal, pois há um hiato, como acontece na palavra “triângulo”."],"correta":3,"explicacao":"Gabarito: <strong>é um exemplo de encontro vocálico, pois há um ditongo, assim como acontece na palavra “lousa”.</strong>.","banca":"CPCON","ano":2024,"temas_relacionados":["encontrosConsonantais","ditongos","hiatos","tritongos"]},{"id":780,"enunciado":"Analise as assertivas a seguir, sobre palavras retiradas do texto, levando em conta os conceitos relacionados à fonologia: I. A palavra “processamento” tem um dígrafo consonantal e um vocálico. II. Nas palavras “mudança” e “rolando” observa-se, em cada uma delas, o mesmo número de letras e fonemas. III. Em “agressividade” há a ocorrência de um encontro consonantal e de um dígrafo. Quais estão corretas?","opcoes":["Apenas I.","Apenas II.","Apenas III.","Apenas I e II.","Apenas I e III."],"correta":4,"explicacao":"Gabarito: <strong>Apenas I e III.</strong>.","banca":"FUNDATEC","ano":2025,"temas_relacionados":["encontrosConsonantais","digrafos","fonemas"]},{"id":781,"enunciado":"Considerando os vocábulos “cognitiva” (l. 08) e “abstinência” (l. 14), analise as assertivas a seguir: I. Ambos os vocábulos possuem uma vogal pronunciada na oralidade entre os encontros consonantais -gn e -bs, respectivamente. II. Um sinônimo adequado para os vocábulos são, respectivamente, “perceptiva” e “abstenção”. III. De acordo com a ocorrência no texto, são palavras que pertencem a classes gramaticais diferentes. Quais estão corretas?","opcoes":["Apenas I.","Apenas II.","Apenas I e II.","Apenas I e III.","Apenas II e III."],"correta":3,"explicacao":"Gabarito: <strong>Apenas I e III.</strong>.","banca":"FUNDATEC","ano":2025,"temas_relacionados":["encontrosConsonantais"]},{"id":788,"enunciado":"Sobre regras gramaticais da língua portuguesa, analise as assertivas abaixo: I. A palavra “trabalhadora” tem um encontro consonantal e um dígrafo. II. As palavras “humildade” e “saciedade” têm o mesmo número de fonemas. III. A palavra “mão” não conta com um encontro vocálico porque a vogal nasal “ã” não entra nessa categoria. Quais estão corretas?","opcoes":["Apenas I.","Apenas III.","Apenas I e II.","Apenas II e III.","I, II e III."],"correta":0,"explicacao":"Gabarito: <strong>Apenas I.</strong>.","banca":"FUNDATEC","ano":2025,"temas_relacionados":["encontrosConsonantais","digrafos","ditongos","hiatos","tritongos","fonemas"]},{"id":792,"enunciado":"A palavra que contém encontro consonantal (quando duas ou mais consoantes aparecem juntas) é:","opcoes":["Beber.","Água.","Brilho.","Pele.","Motivos."],"correta":2,"explicacao":"Gabarito: <strong>Brilho.</strong>.","banca":"FUNDATEC","ano":2025,"temas_relacionados":["encontrosConsonantais"]},{"id":793,"enunciado":"Encontro consonantal é a sequência de duas ou mais consoantes na mesma palavra, mantendo-se cada som distinto na pronúncia, como em \"próximo\" e \"clínica\". Com base nisso, assinale a única alternativa em que NÃO há uma palavra com encontro consonantal:","opcoes":["Transplante.","Fibromialgia.","Imunológico.","Psicoterapia."],"correta":2,"explicacao":"Gabarito: <strong>Imunológico.</strong>.","banca":"Instituto Fênix","ano":2025,"temas_relacionados":["encontrosConsonantais"]},{"id":803,"enunciado":"Considerando a definição de dígrafos/encontros consonantais, assinale a alternativa INCORRETA.","opcoes":["Não há encontro consonantal em \"imagem\".","Há um encontro consonantal em \"lembrar\".","Há um dígrafo consonantal em \"parques\".","Há um dígrafo consonantal em \"quando\".","Há tanto dígrafo consonantal quanto encontro consonantal em \"trabalho\"."],"correta":3,"explicacao":"Gabarito: <strong>Há um dígrafo consonantal em \"quando\".</strong>.","banca":"FAFIPA","ano":2024,"temas_relacionados":["encontrosConsonantais","digrafos"]},{"id":821,"enunciado":"Encontro consonantal é quando duas ou mais consoantes aparecem juntas em uma palavra, sem vogal entre elas. Sabendo-se disso, assinale a alternativa correta sobre os encontros consonantais nas palavras a seguir.","opcoes":["“crônicas” – apresenta um encontro consonantal disjunto.","“doenças” – apresenta um encontro consonantal disjunto.","“frequência” – apresenta um encontro consonantal puro.","“importantes” – apresenta um encontro consonantal puro."],"correta":2,"explicacao":"Gabarito: <strong>“frequência” – apresenta um encontro consonantal puro.</strong>.","banca":"Instituto Darwin","ano":2024,"temas_relacionados":["encontrosConsonantais"]},{"id":822,"enunciado":"Assinale a alternativa correta na qual todas as palavras são formadas por encontros consonantais.","opcoes":["história – planeta.","observadas – Terra.","mudanças – climáticas.","evolutiva – intrinsecamente."],"correta":0,"explicacao":"Gabarito: <strong>história – planeta.</strong>.","banca":"Instituto Darwin","ano":2024,"temas_relacionados":["encontrosConsonantais"]},{"id":825,"enunciado":"Indique quantos encontros consonantais há na tirinha analisada:","opcoes":["Nenhum.","Um.","Dois.","Três."],"correta":3,"explicacao":"Gabarito: <strong>Três.</strong>.","banca":"DAE de Bauru - SP","ano":2024,"temas_relacionados":["encontrosConsonantais"]},{"id":836,"enunciado":"Na palavra EQUILIBRADO, há:","opcoes":["dois dígrafos","dois encontros consonantais","um hiato e um encontro consonantal","um dígrafo e um encontro consonantal"],"correta":3,"explicacao":"Gabarito: <strong>um dígrafo e um encontro consonantal</strong>.","banca":"SELECON","ano":2024,"temas_relacionados":["encontrosConsonantais","digrafos"]},{"id":837,"enunciado":"No título do texto, há, quanto ao número de encontros consonantais, apenas:","opcoes":["1.","2.","3.","4.","5."],"correta":1,"explicacao":"Gabarito: <strong>2.</strong>.","banca":"CONTEMAX","ano":2024,"temas_relacionados":["encontrosConsonantais"]},{"id":840,"enunciado":"Assinale a alternativa em que as palavras contêm encontro consonantal:","opcoes":["elipse e choro.","zeugma e omissão.","elipse e aparece","zeugma e elipse."],"correta":3,"explicacao":"Gabarito: <strong>zeugma e elipse.</strong>.","banca":"FUNDEP (Gestão de Concursos)","ano":2021,"temas_relacionados":["encontrosConsonantais"]},{"id":842,"enunciado":"Qual das palavras a seguir possui um encontro consonantal situado em sílabas diferentes?","opcoes":["Blusa.","Livro.","Prato.","Barco."],"correta":3,"explicacao":"Gabarito: <strong>Barco.</strong>.","banca":"Itame","ano":2024,"temas_relacionados":["encontrosConsonantais","silabas"]},{"id":852,"enunciado":"Assinale a alternativa, onde não temos encontro consonantal.","opcoes":["Placa.","Pedregulho.","Dragão.","Vidro.","Cores."],"correta":4,"explicacao":"Gabarito: <strong>Cores.</strong>.","banca":"MSConcursos","ano":2023,"temas_relacionados":["encontrosConsonantais"]},{"id":853,"enunciado":"Assinale a alternativa, onde não temos encontro consonantal.","opcoes":["Duro.","Pneu.","Cobra.","Adriana.","Pedra."],"correta":0,"explicacao":"Gabarito: <strong>Duro.</strong>.","banca":"MSConcursos","ano":2024,"temas_relacionados":["encontrosConsonantais"]},{"id":857,"enunciado":"Nas palavras primeira (linha 2) e arrebatado (linha 7) há, respectivamente,","opcoes":["dígrafo e encontro consonantal.","encontro consonantal e encontro consonantal.","encontro consonantal e dígrafo.","dígrafo e dígrafo."],"correta":2,"explicacao":"Gabarito: <strong>encontro consonantal e dígrafo.</strong>.","banca":"COMPERVE - UFRN","ano":2008,"temas_relacionados":["encontrosConsonantais","digrafos"]},{"id":860,"enunciado":"Assinale a opção que contém uma palavra em que ocorre encontro consonantal:","opcoes":["Ator.","Pneu.","Pacote.","Girafa."],"correta":1,"explicacao":"Gabarito: <strong>Pneu.</strong>.","banca":"FAFIPA","ano":2016,"temas_relacionados":["encontrosConsonantais"]},{"id":863,"enunciado":"A fonética é o estudo dos sons da fala e trata dos fonemas, da pronúncia correta das palavras, da exata acentuação tônica e da configuração gráfica ou a escrita correta das palavras, denominada ortografia. Considere esse conceito e leia a tirinha. Imagem associada para resolução da questão Disponível em: <https://www.nsctotal.com.br/noticias/confira-a-tira-do-armandinho-desta-terca-feira-4>. Avalie o que se informa acerca das palavras que compõem o texto da tirinha. I – A palavra “extintas” deve ser acentuada, pois se trata de uma paroxítona terminada em “s”. II – A expressão “preguiças-gigantes” foi grafada com hífen porque corresponde a um adjetivo composto. III – O último quadrinho da tira traz alguns vocábulos formados por ditongo, dígrafo e encontro consonantal. Está correto apenas o que se afirma em","opcoes":["II.","III.","I e II.","I e III."],"correta":1,"explicacao":"Gabarito: <strong>III.</strong>.","banca":"FCM","ano":2022,"temas_relacionados":["encontrosConsonantais","ditongos","digrafos","paroxitonas","fonemas","ortografia","hifen"]},{"id":864,"enunciado":"Assinale a alternativa que mostra uma palavra retirada do texto em que NÃO há encontro consonantal.","opcoes":["traços.","espadas.","significativo.","contatos.","cirurgia."],"correta":3,"explicacao":"Gabarito: <strong>contatos.</strong>.","banca":"FUNDATEC","ano":2022,"temas_relacionados":["encontrosConsonantais"]},{"id":875,"enunciado":"Assinale a alternativa que apresenta uma palavra com encontro consonantal.","opcoes":["Recursos.","Naturais.","Futuro.","Poluição.","Cidades."],"correta":0,"explicacao":"Gabarito: <strong>Recursos.</strong>.","banca":"FUNDATEC","ano":2024,"temas_relacionados":["encontrosConsonantais"]},{"id":884,"enunciado":"Considerando-se o trecho “Muitas vezes pensei quão interessantemente podia ser escrita uma revista, por um autor que quisesse, isto é, que pudesse, pormenorizar, passo a passo, os processos pelos quais qualquer uma de suas composições atingia seu ponto de acabamento.”, analisar os itens. I. Há seis ocorrências do dígrafo consonantal -ss. II. Há sete ocorrências do dígrafo consonantal -qu. III. Há mais de uma ocorrência de encontro consonantal. Está CORRETO o que se afirma:","opcoes":["Apenas no item I.","Apenas no item II.","Apenas nos itens I e III.","Em todos os itens."],"correta":2,"explicacao":"Gabarito: <strong>Apenas nos itens I e III.</strong>.","banca":"OBJETIVA","ano":2024,"temas_relacionados":["encontrosConsonantais","digrafos"]},{"id":1452,"enunciado":"Leia o poema “Igreja”, de Carlos Drummond de Andrade, para responder à questão. Tijolo areia andaime água tijolo. O canto dos homens trabalhando trabalhando mais perto do céu cada vez mais perto mais — a torre. E nos domingos a litania dos perdões, o murmúrio das invocações. O padre que fala do inferno sem nunca ter ido lá. Pernas de seda ajoelham mostrando geolhos. Um sino canta a saudade de qualquer coisa sabida e já esquecida. A manhã pintou-se de azul. No adro ficou o ateu, no alto fica Deus. Domingo... Bem bão! Bem bão! Os serafins, no meio, entoam quii ieleisão. Após ler o poema modernista de Carlos Drummond de Andrade, observe que o poeta empregou um arcaísmo – “geolhos” – no quarto verso da segunda estrofe, o qual resultaria hoje na palavra joelhos. Identifique o processo de mudança ocorrida nesse vocábulo, marcando a opção que considera correta:","opcoes":["Houve uma mudança vocabular denominada consonalização por aglutinação.","Houve um metaplasmo por dissimilação denominado paragoge.","Houve uma transformação nesse vocábulo a que chamamos epêntese.","Houve um metaplasmo por transposição por deslocamento (metátese).","Houve uma alteração fonética nesse termo identificada como aférese."],"correta":3,"explicacao":"Gabarito: <strong>Houve um metaplasmo por transposição por deslocamento (metátese).</strong>.","banca":"IF-PA","ano":2022,"temas_relacionados":["encontrosConsonantais"]},{"id":1527,"enunciado":"As sílabas podem ser classificadas em simples e compostas, dependendo da quantidade de fonemas e da estrutura dos encontros vocálicos e consonantais que apresentam (BECHARA, 2019). Assinale a alternativa correta quanto ao tipo de sílaba apresentada no vocábulo.","opcoes":["\"ca-sa\" (duas sílabas simples: ca e sa).","\"Uruguai\" (ditongo) - sílaba composta por encontro consonantal.","\"pla-no\" (pla e no) − sílaba composta por encontro vocálico.","\"bo-la\" (duas sílabas compostas: bo e la)."],"correta":0,"explicacao":"Gabarito: <strong>\"ca-sa\" (duas sílabas simples: ca e sa).</strong>.","banca":"AMEOSC","ano":2025,"temas_relacionados":["encontrosConsonantais","silabas","fonemas"]},{"id":1537,"enunciado":"Em “Já procurei caxangá, caxengá e caxingá, com ‘x’ e ‘ch’”, caso os vocábulos fossem reescritos com “ch”, quanto à natureza fonética/fonológica, é correto afirmar que:","opcoes":["não haveria alteração no número de fonemas.","diminuiria o número de letras das palavras.","se faria a inclusão de um encontro consonantal.","haveria mudança na pronúncia dos vocábulos.","ocorreria acréscimo de encontro vocálico."],"correta":0,"explicacao":"Gabarito: <strong>não haveria alteração no número de fonemas.</strong>.","banca":"IBFC","ano":2025,"temas_relacionados":["encontrosConsonantais","fonemas"]},{"id":1562,"enunciado":"A palavra \"descobertas\", em relação à grafia e à análise linguística:","opcoes":["Possui um dígrafo consonantal.","Não contém dígrafos, mas apresenta um único encontro vocálico.","Tem dois encontros consonantais.","Apresenta apenas três fonemas vocálicos."],"correta":2,"explicacao":"Gabarito: <strong>Tem dois encontros consonantais.</strong>.","banca":"Instituto Fênix","ano":2025,"temas_relacionados":["encontrosConsonantais","ortografia"]},{"id":1585,"enunciado":"Sobre a palavra “humano”, é correto afirmar que:","opcoes":["Contém duas sílabas, portanto é dissílaba.","Contém 5 fonemas.","Contém 5 letras.","Está no plural.","Contém um encontro consonantal."],"correta":1,"explicacao":"Gabarito: <strong>Contém 5 fonemas.</strong>.","banca":"FUNDATEC","ano":2024,"temas_relacionados":["encontrosConsonantais","fonemas"]},{"id":1655,"enunciado":"Marque a afirmação incorreta.","opcoes":["“Nove” é um numeral cardinal.","A palavra \"traidor\" (tra-i-dor) se estrutura com encontro consonantal e hiato.","“Quais” (qua-is) é dissílabo oxítono.","A sequência: “você; irá; descobrir; depois; sair” registra somente exemplos de palavras oxítonas.","As palavras: “típico”; “técnico” e “hipóteses” não têm o mesmo número de sílabas gramaticais, mas pertencem à mesma regra de acentuação."],"correta":2,"explicacao":"Gabarito: <strong>“Quais” (qua-is) é dissílabo oxítono.</strong>.","banca":"CONCEPÇÃO","ano":2012,"temas_relacionados":["encontrosConsonantais","hiatos","silabas","oxitonas"]},{"id":1685,"enunciado":"Julgue o item subsequente.\nA aliteração é uma figura de som que envolve a repetição intencional de sons consonantais no início ou ao longo de palavras próximas, utilizada para conferir ritmo e harmonia ao texto, além de enfatizar o significado ou criar uma atmosfera específica. Por exemplo, no verso \"Vozes veladas, veludosas vozes,\" de Cruz e Sousa, a repetição do som /v/ contribui para criar uma sensação de suavidade e mistério.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"IGEDUC","ano":2024,"tipo":"certo_errado","temas_relacionados":["encontrosConsonantais"]},{"id":1706,"enunciado":"Considerando a fonética da Língua Portuguesa, analise as assertivas abaixo: I. A palavra “transação” tem um encontro consonantal, um dígrafo e um encontro vocálico. II. Tanto “agasalho” quanto “queixada” têm 8 letras e 7 fonemas. III. “Pneu” e “digníssimo” têm encontros consonantais. Quais estão corretas?","opcoes":["Apenas I.","Apenas II.","Apenas I e III.","Apenas II e III.","I, II e III."],"correta":4,"explicacao":"Gabarito: <strong>I, II e III.</strong>.","banca":"FUNDATEC","ano":2024,"temas_relacionados":["encontrosConsonantais","digrafos","ditongos","hiatos","tritongos","fonemas"]},{"id":5106,"enunciado":"Acerca da análise linguística do vocábulo “conscientização”, assinale a alternativa INCORRETA.","opcoes":["É composto por um hiato entre a segunda e a terceira sílabas.","Possui dígrafo na terceira sílaba.","É composto por um encontro consonantal na primeira sílaba.","Está no grau aumentativo."],"correta":3,"explicacao":"Gabarito: <strong>Está no grau aumentativo.</strong>.","banca":"IDESG","ano":2024,"temas_relacionados":["encontrosConsonantais","hiatos","digrafos","silabas"]}];
